/* Example: styling a card-like element */
.card {
    padding: 20px;
    background-color: #f0f0f0;
    border-radius: 8px;
    box-shadow: 0 4px 8px rgba(0,0,0,0.1);
}

/* Similar: enabling grid layout on a container */
.container {
  display: grid;
}

/* Example: creating a grid with fixed columns */
.grid-container {
  display: grid;
  grid-template-columns: repeat(4, 150px);
}

/* Similar: adding spacing to a grid container */
.grid-container {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 15px;
}

